const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  function eeGet(obj) {
    return new Promise((resolve, reject) => {
      obj.evaluate((v, e) => (e ? reject(e) : resolve(v)));
    });
  }

  try {
    // 1. Geometry & Time Definitions
    const gaul = ee.FeatureCollection('FAO/GAUL/2015/level1');
    let peten = gaul
      .filter(ee.Filter.eq('ADM0_NAME', 'Guatemala'))
      .filter(ee.Filter.eq('ADM1_NAME', 'Petén'));
    let size1 = await eeGet(peten.size());
    if (size1 === 0) {
      peten = gaul
        .filter(ee.Filter.eq('ADM0_NAME', 'Guatemala'))
        .filter(ee.Filter.eq('ADM1_NAME', 'Peten'));
      size1 = await eeGet(peten.size());
    }
    if (size1 === 0) {
      peten = gaul
        .filter(ee.Filter.eq('ADM0_NAME', 'Guatemala'))
        .filter(ee.Filter.stringContains('ADM1_NAME', 'Pet'));
      size1 = await eeGet(peten.size());
    }
    if (size1 === 0) {
      console.log('Region lookup failed: Petén not found in GAUL.');
      console.log('D');
      return;
    }
    const region = peten.union(1).geometry();

    // 2. Data Acquisition & Check
    const gfc = ee.Image('UMD/hansen/global_forest_change_2023_v1.11');
    const tc2000 = gfc.select('treecover2000');
    const lossyear = gfc.select('lossyear');
    const datamask = gfc.select('datamask').eq(1); // land

    // Threshold for forest
    const thr = 30;
    const baseForest = tc2000.gte(thr);

    // Forest masks (end of year)
    const forest2001 = datamask.and(baseForest).and(lossyear.neq(1));
    const forest2023 = datamask.and(baseForest).and(lossyear.eq(0));

    // 3. Processing: pixel counts and area (km2) at 1 km scale
    const areaKm2 = ee.Image.pixelArea().divide(1e6);
    const ones2001 = ee.Image.constant(1).updateMask(forest2001);
    const ones2023 = ee.Image.constant(1).updateMask(forest2023);
    const onesRegion = ee.Image.constant(1).updateMask(datamask);

    const regArea = await eeGet(
      areaKm2.updateMask(datamask).reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: region,
        scale: 1000,
        maxPixels: 1e13,
      })
    );
    const a2001 = await eeGet(
      areaKm2.updateMask(forest2001).reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: region,
        scale: 1000,
        maxPixels: 1e13,
      })
    );
    const a2023 = await eeGet(
      areaKm2.updateMask(forest2023).reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: region,
        scale: 1000,
        maxPixels: 1e13,
      })
    );
    const c2001 = await eeGet(
      ones2001.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: region,
        scale: 1000,
        maxPixels: 1e13,
      })
    );
    const c2023 = await eeGet(
      ones2023.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: region,
        scale: 1000,
        maxPixels: 1e13,
      })
    );
    const cRegion = await eeGet(
      onesRegion.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: region,
        scale: 1000,
        maxPixels: 1e13,
      })
    );

    const regionAreaKm2 = regArea ? regArea.pixelarea : null;
    const area2001 = a2001 ? a2001.pixelarea : null;
    const area2023 = a2023 ? a2023.pixelarea : null;
    const count2001 = c2001 ? c2001.constant : 0;
    const count2023 = c2023 ? c2023.constant : 0;
    const countRegion = cRegion ? cRegion.constant : 0;

    // 4. Validation
    if (
      regionAreaKm2 === null ||
      area2001 === null ||
      area2023 === null ||
      !isFinite(regionAreaKm2) ||
      !isFinite(area2001) ||
      !isFinite(area2023)
    ) {
      console.log('Calculation produced null/invalid values.');
      console.log('C3');
      return;
    }
    if (count2001 === 0 || count2023 === 0) {
      console.log(
        `No valid pixels after masking. 2001_px=${count2001}, 2023_px=${count2023}`
      );
      console.log('C2');
      return;
    }

    // 5. Results & Final Answer
    const change = area2023 - area2001;
    const pct = (change / area2001) * 100;
    console.log('Region: Petén, Guatemala (GAUL 2015 L1)');
    console.log('Dataset: Hansen GFC v1.11, forest ≥30% canopy, land mask applied');
    console.log(
      `Region land area (km²): ${Math.round(regionAreaKm2)} | Cells(1km): ${countRegion}`
    );
    console.log(
      `2001 end-year forest (km²): ${Math.round(area2001)} | Cells: ${count2001}`
    );
    console.log(
      `2023 end-year forest (km²): ${Math.round(area2023)} | Cells: ${count2023}`
    );
    console.log(
      `Change (km²): ${Math.round(change)} | Change (% of 2001): ${pct.toFixed(2)}`
    );

    // Tolerance to avoid rounding artifacts
    const tolKm2 = Math.max(1, 0.001 * area2001);
    const decreased = area2023 < area2001 - tolKm2;
    console.log(decreased ? 'A' : 'B');
  } catch (err) {
    console.log(`Error: ${err.message || err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
